#include "s5krc1s_decoder.hpp"
#include "trace.hpp"
#include <iostream>
#include <array>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("legacy_replay file reference|dual");ab::start();S5KRC1SPacketDecoder d;if(!d.init(960,720,1))throw std::runtime_error("init");d.set_gen4_chid_mode(true);d.set_reference_b3_only(std::string(argv[2])=="reference");d.set_same_group_b2b3(false);d.set_legacy_frame_end(false);d.set_debug_event_limit(0);d.set_invalid_sample_limit(0);d.set_polarity_sample_limit(0);std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("input");std::ofstream control(std::string(std::getenv("AB_TRACE_PREFIX"))+".control.csv");unsigned ref=0;std::array<std::uint8_t,4>b;DVSDecodeTotals totals{};std::uint64_t emitted=0;while(f.read(reinterpret_cast<char*>(b.data()),4)){ab::begin(b.data());std::vector<DVSEvent> out;DVSDecodeStats s;if(!d.decode_batch(b.data(),4,0,0,out,s))throw std::runtime_error("decode");add_decode_stats(totals,s);if(s.is_new_ts_ref)ref=s.ts_current;if(s.is_new_ts_sub)control<<ab::current<<','<<(std::uint64_t(ref)*1000+s.ts_current)<<'\n';for(auto&e:out){ab::event(ab::cid,e.x,e.y,1,e.polarity);++emitted;}}std::cout<<"{\"mode\":\""<<argv[2]<<"\",\"events\":"<<totals.raw_events_total<<",\"emitted\":"<<emitted<<",\"on\":"<<totals.on_events_total<<",\"off\":"<<totals.off_events_total<<",\"columns\":"<<totals.column_packets<<",\"group_words\":"<<totals.group_packets<<",\"timestamp_words\":"<<totals.timestamp_packets<<",\"end_packets\":"<<totals.end_packets<<",\"invalid_x\":"<<totals.invalid_x<<",\"invalid_y\":"<<totals.invalid_y<<",\"unknown\":"<<totals.other_packets<<",\"sensor_time_comparable\":false}\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
